import assert from 'node:assert/strict';
import test from 'node:test';
import { total } from './app.mjs';
test('zero and defaults',()=>{const input=[0,2,undefined];assert.equal(total(input),12);assert.deepEqual(input,[0,2,undefined]);assert.equal(total([]),0);});

import assert from 'node:assert/strict';
import test from 'node:test';
import { money } from './money.mjs';
import { invoice } from './invoice.mjs';
test('formatting contract',()=>{assert.equal(money(125),'1.25');assert.equal(money(-5),'-0.05');assert.equal(invoice(0),'USD 0.00');assert.equal(invoice(1234),'USD 12.34');});

import assert from 'node:assert/strict';
import test from 'node:test';
import { ordered } from './app.mjs';
test('numeric and immutable',()=>{const values=[10,2,2,1];assert.deepEqual(ordered(values),[1,2,2,10]);assert.deepEqual(values,[10,2,2,1]);assert.deepEqual(ordered([]),[]);});

import assert from 'node:assert/strict';
import test from 'node:test';
import {readFileSync} from 'node:fs';
test('documentation scope',()=>{const text=readFileSync('README.md','utf8');assert.match(text,/ephemeral/i);assert.match(text,/cannot resume/i);assert.match(text,/node --test acceptance\.test\.mjs/);assert.equal(readFileSync('app.mjs','utf8'),"export const mode = 'ephemeral';\n");});

import assert from 'node:assert/strict';
import test from 'node:test';
import {readFileSync} from 'node:fs';
test('bounded evidence answer',()=>{const result=JSON.parse(readFileSync('answer.json','utf8'));assert.equal(result.selected,'local');assert.deepEqual(result.evidence,['source-a','source-b']);assert.equal(result.uncertainty,'quality unmeasured');});

import assert from 'node:assert/strict';
import test from 'node:test';
import {finish} from './app.mjs';
test('late results cannot revive cancelled work',()=>{const state={status:'cancelled',result:null};assert.deepEqual(finish(state,'late'),state);assert.deepEqual(state,{status:'cancelled',result:null});assert.deepEqual(finish({status:'running',result:null},'done'),{status:'completed',result:'done'});});

import assert from 'node:assert/strict';
import test from 'node:test';
import {recover} from './app.mjs';
test('restart revokes old authorization',()=>{for(const status of ['running','clarification','completed'])assert.deepEqual(recover({status,authorized:true}),{status:'interrupted',authorized:false,replay:false});});

import assert from 'node:assert/strict';
import test from 'node:test';
import {record} from './app.mjs';
test('completion records are idempotent',()=>{const ids=['a'];assert.deepEqual(record(ids,'a'),['a']);assert.deepEqual(record(ids,'b'),['a','b']);assert.deepEqual(ids,['a']);assert.deepEqual(record(record([],'x'),'x'),['x']);});

import assert from 'node:assert/strict';
import test from 'node:test';
import {ready} from './app.mjs';
test('dependencies and gate',()=>{assert.equal(ready({dependencies:['a'],gate:true},{a:'failed'}),false);assert.equal(ready({dependencies:['a'],gate:false},{a:'accepted'}),false);assert.equal(ready({dependencies:['a'],gate:true},{}),false);assert.equal(ready({dependencies:['a'],gate:true},{a:'accepted'}),true);assert.equal(ready({dependencies:[],gate:true},{}),true);});

import assert from 'node:assert/strict';
import test from 'node:test';
import {accepted} from './app.mjs';
test('exact evidence binding',()=>{const current={treeHash:'tree',artifactHash:'artifact'};assert.equal(accepted({...current,exitCode:0},current),true);assert.equal(accepted({...current,treeHash:'old',exitCode:0},current),false);assert.equal(accepted({...current,artifactHash:'old',exitCode:0},current),false);assert.equal(accepted({...current,exitCode:1},current),false);assert.equal(accepted({exitCode:0},{}),false);});
